prompt --application/shared_components/plugins/template_component/amc_next_org_chart
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(393756357195752952)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_ORG_CHART'
,p_display_name=>'Next Org Chart'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NOrgChart-card">',
'  <span class="amc-NOrgChart-avatar">{if ?IMAGE_URL/}<img class="amc-NOrgChart-img" src="#IMAGE_URL#" alt="" width="48" height="48" loading="lazy">{else/}<span class="amc-NOrgChart-initials" aria-hidden="true">{if ?INITIALS/}#INITIALS#{else/}<span class="fa fa-user-o"></span>{endif/}</span>{endif/}</span>',
'  <span class="amc-NOrgChart-text">',
'    <span class="amc-NOrgChart-name">{if ?LINK_URL/}<a class="amc-NOrgChart-link" href="#LINK_URL#">{if ?NAME/}#NAME#{else/}Vacant position{endif/}</a>{else/}{if ?NAME/}#NAME#{else/}Vacant position{endif/}{endif/}</span>',
'    {if ?TITLE/}<span class="amc-NOrgChart-job">#TITLE#</span>{endif/}',
'    {if ?DEPARTMENT/}<span class="amc-NOrgChart-dept">#DEPARTMENT#</span>{endif/}',
'    {if ?NAME/}{case VACANT/}{when Y/}<span class="amc-NOrgChart-vacant">Vacant position</span>{when y/}<span class="amc-NOrgChart-vacant">Vacant position</span>{when yes/}<span class="amc-NOrgChart-vacant">Vacant position</span>{when YES/}<span class="amc-NOrgChart-vacant">Vacant position</span>{when Yes/}<span class="amc-NOrgChart-vacant">Vacant position</span>{otherwise/}{endcase/}{endif/}',
'  </span>',
'</div>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-NOrgChart amc-NOrgChart--#STYLE#" data-layout="#STYLE#" data-expand="#EXPAND_LEVELS#" data-search="#SHOW_SEARCH#">',
'  <span class="amc-NOrgChart-i18n" hidden data-search="Find a person" data-search-hint="Name, job title or department" data-clear="Clear search" data-no-match="No one matches" data-match-one="match" data-match-other="matches" data-vacant="Vacant position" data-zoom-in="Zoom in" data-zoom-out="Zoom out" data-fit="Fit chart" data-expand-all="Open all" data-collapse-all="Close all" data-reports-one="direct report" data-reports-other="direct reports" data-team="in team" data-reports-to="Reports to" data-people-one="person" data-people-other="people" data-vacant-one="vacant position" data-vacant-other="vacant positions" data-other="Other" data-chart="Organization chart" data-of="of"></span>',
'  <ul class="amc-NOrgChart-source">#APEX$ROWS#</ul>',
'</div>'))
,p_report_row_template=>'<li class="amc-NOrgChart-row amc-NOrgChart-row--l{case LEVEL/}{when 1/}1{when 2/}2{when 3/}3{when 4/}4{when 5/}5{when 6/}6{when 7/}7{when 8/}8{otherwise/}0{endcase/}{case VACANT/}{when Y/} amc-NOrgChart-row--vacant{when y/} amc-NOrgChart-row--vacant{when yes/} amc-NOrgChart-row--vacant{when YES/} amc-NOrgChart-row--vacant{when Yes/} amc-NOrgChart-row--vacant{otherwise/}{endcase/}" data-id="#ID#" data-parent="#PARENT_ID#" data-department="#DEPARTMENT!ATTR#" data-vacant="#VACANT#" data-headcount="#HEADCOUNT#">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-org-chart.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-org-chart.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'One query row per position. Map ID (required) and Parent ID: the ID of the manager''s row, empty for the top of the chart. Rows may arrive in any order; a CONNECT BY query with ORDER SIBLINGS BY and LEVEL gives the best result without JavaScript. Name is the person, Job Title their role, Department groups the swimlanes. Set Vacant to Y for an open position; its Name may stay empty. Headcount is the size of the whole team under a person; when empty the chart counts the people it has. The runtime file builds the tree, search, keyboard navigation and zoom, and rebuilds after a region refresh.'
,p_version_identifier=>'1.0.1'
,p_files_version=>2
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(327013312686276021)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'topDown'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Layout of the chart; the direction is given in brackets as motion, depth, bold or smart. topDown [depth]: the classic chart for a leadership or intranet page; name plates joined by connectors, a collapsed team shows as a stack of plates, and teams without managers below them stack vertically. leftToRight [smart]: each level is a column, for deep hierarchies such as a ministry''s directorates; in regions narrower than about 560px it becomes an indented outline. swimlanes [bold]: one lane per Department with its people, headcount and vacant positions, for restructuring and workforce planning; a lane''s top person shows who they report to in another department. radial [motion]: the lead in the centre and the team on rings around them, for project teams of up to about 25 people; opened branches grow out of their manager. directory [smart]: a staff directory grouped under managers; search filters the list and each result shows its chain of command.'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(403839997019521884)
,p_plugin_attribute_id=>wwv_flow_imp.id(327013312686276021)
,p_display_sequence=>10
,p_display_value=>'Top-down chart'
,p_return_value=>'topDown'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(576988476485643037)
,p_plugin_attribute_id=>wwv_flow_imp.id(327013312686276021)
,p_display_sequence=>20
,p_display_value=>'Left to right'
,p_return_value=>'leftToRight'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(361958685706772061)
,p_plugin_attribute_id=>wwv_flow_imp.id(327013312686276021)
,p_display_sequence=>30
,p_display_value=>'Department swimlanes'
,p_return_value=>'swimlanes'
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(296937513931625289)
,p_plugin_attribute_id=>wwv_flow_imp.id(327013312686276021)
,p_display_sequence=>40
,p_display_value=>'Radial team'
,p_return_value=>'radial'
);
