 p_id=>wwv_flow_imp.id(543846896475126098)
,p_plugin_attribute_id=>wwv_flow_imp.id(327013312686276021)
,p_display_sequence=>50
,p_display_value=>'Staff directory'
,p_return_value=>'directory'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(332554540988246485)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_static_id=>'ID'
,p_prompt=>'ID'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>true
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Unique key of the row, for example the position or employee ID. Parent ID of the people who report to this row refers to it.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(861393397487098948)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_static_id=>'PARENT_ID'
,p_prompt=>'Parent ID'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'ID of the manager''s row. Leave empty for the top of the chart. A row whose manager is not in the query, or that would create a loop, is shown as another top-level person, so a filtered query still renders.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(887042168724992519)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_static_id=>'NAME'
,p_prompt=>'Name'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Person''s name, for example Noura Al-Qahtani. May be empty for a vacant position, which then reads Vacant position.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(784834336499834799)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_static_id=>'TITLE'
,p_prompt=>'Job Title'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Job title in sentence case, for example Head of treasury or Warehouse manager, Jebel Ali. Search also matches it.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(698932876169012027)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>60
,p_static_id=>'DEPARTMENT'
,p_prompt=>'Department'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'Department or unit, for example Finance or Customs and trade compliance. It makes the lanes of the swimlanes style, where rows without a department go to an Other lane, and search matches it.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(529034254815874674)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_static_id=>'IMAGE_URL'
,p_prompt=>'Image URL'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional photo URL, for example from apex_util.get_blob_file_src or an Object Storage link. Shown as a round portrait; when empty the Initials are shown.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(470334045132571727)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_static_id=>'INITIALS'
,p_prompt=>'Initials'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'HTML'
,p_is_translatable=>false
,p_help_text=>'One or two letters shown when there is no photo, for example NQ. Compute them in SQL, for example upper(substr(first_name, 1, 1) || substr(last_name, 1, 1)).'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(671724506168621251)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>9
,p_display_sequence=>90
,p_static_id=>'LINK_URL'
,p_prompt=>'Link URL'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional target of the person''s name, usually built in SQL with apex_page.get_url, for example to the employee record. Enter on a focused person opens it. The URL must come from the developer, not from user input.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(271796792011979699)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>10
,p_display_sequence=>100
,p_static_id=>'VACANT'
,p_prompt=>'Vacant'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Y for an open position, N or empty for a filled one; yes and no are also accepted. Vacant positions show as a hatched, dashed plate labelled Vacant position, and are counted separately in team and lane totals.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(587501080914945318)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>11
,p_display_sequence=>110
,p_static_id=>'HEADCOUNT'
,p_prompt=>'Headcount'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional whole number: people in this person''s whole team, for example 214 for a head of operations whose team is not all in the query. When empty the chart counts the filled positions below the person that are in the query.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(394556878904452719)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>12
,p_display_sequence=>120
,p_static_id=>'LEVEL'
,p_prompt=>'Level'
,p_attribute_type=>'SESSION STATE VALUE'
,p_is_required=>false
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Optional depth, 1 for the top, usually LEVEL from a CONNECT BY query ordered with ORDER SIBLINGS BY. Only used to indent the outline list shown without JavaScript, up to 8 levels; the runtime file works out the tree from Parent ID.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(122508112863048452)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>13
,p_display_sequence=>130
,p_static_id=>'EXPAND_LEVELS'
,p_prompt=>'Open Levels'
,p_attribute_type=>'INTEGER'
,p_is_required=>false
,p_default_value=>'2'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Number of levels open when the chart loads, 1 to 12. With 2 the top person and their direct reports are visible and deeper teams start collapsed. Search opens any branch it needs. The staff directory always opens every level.'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(928620481858819723)
,p_plugin_id=>wwv_flow_imp.id(393756357195752952)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>14
,p_display_sequence=>140
,p_static_id=>'SHOW_SEARCH'
,p_prompt=>'Show Search'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_help_text=>'Y shows a Find a person field above the chart that matches names, job titles and departments, opens the branches it needs and scrolls to the person. N hides it, for small charts.'
);
end;
/
